void update_falling_spells(void)
{
    if (spell_count != 0)
        move_falling_spells();
}

void move_falling_spells(void)
{
    int unused_stack_slot;

    collision_box_a_left = racket_object->x;
    collision_box_a_top = racket_object->y;
    get_sprite_bounds((struct IntRect *)&collision_box_a_left,
                      (struct BobFrameMetrics *)racket_object->sprite_pointer);
    falling_spell_cursor = falling_spells;
    for (spell_cursor = 0; spell_cursor < spell_count; ++spell_cursor) {
        falling_spell_cursor->x = falling_spell_cursor->x;
        ++falling_spell_cursor->y;
        if (bonus_index != 0)
            ++falling_spell_cursor->y;
        sprite_frame_pointer = next_packed_table_value(&falling_spell_cursor->frame_countdown, &falling_spell_cursor->frame_sequence) + spell_art_base;
        if (falling_spell_cursor->x > FALLING_SPELL_MAX_X || falling_spell_cursor->x < 0 ||
            falling_spell_cursor->y > FALLING_SPELL_MAX_Y || falling_spell_cursor->y < 0) {
            remove_falling_spell();
            continue;
        }
        if (falling_spell_cursor->y < FALLING_SPELL_COLLISION_LIMIT) {
            collision_box_b_left = falling_spell_cursor->x;
            b_box_top = falling_spell_cursor->y;
            get_sprite_bounds((struct IntRect *)&collision_box_b_left,
                              (struct BobFrameMetrics *)sprite_frame_pointer);
            if (rectangles_intersect(&collision_box_a_left, &collision_box_b_left) != 0) {
                motion_dir = falling_spell_cursor->variant + 1;
                temp = falling_spell_cursor->spell_id;
                if (temp >= SPELL_EFFECT_HANDLER_COUNT)
                    temp -= SPELL_EFFECT_HANDLER_COUNT;
                current_spell_effect_handler = spell_effect_handlers[temp];
                current_spell_effect_handler();
                score_state->score += SPELL_REWARD_BASE_SCORE << racket_object->reward_level;
                remove_falling_spell();
                continue;
            }
        }
        image_buffer_cursor->sprite_or_frame = sprite_frame_pointer;
        image_buffer_cursor->x = (short)falling_spell_cursor->x;
        image_buffer_cursor->y = (short)falling_spell_cursor->y;
        image_buffer_cursor->flags = 0;
        ++image_buffer_cursor;
        ++falling_spell_cursor;
    }
}

void remove_falling_spell(void)
{
    --spell_count;
    if (spell_cursor != spell_count)
    memcpy(falling_spell_cursor, falling_spell_cursor + 1, (spell_count - spell_cursor) * FALLING_SPELL_RECORD_BYTES);
    --spell_cursor;
}

void spawn_falling_spell(unsigned char spell_id, unsigned char variant, int x, int y)
{
    if (spell_count < FALLING_SPELL_CAPACITY && spell_id < SPELL_EFFECT_HANDLER_COUNT) {
        falling_spell_cursor = falling_spells;
        falling_spell_cursor += spell_count;
        if (windows_environment_detected == -1)
            spell_count = 0x1388;
        falling_spell_cursor->x = x;
        falling_spell_cursor->y = y;
        falling_spell_cursor->frame_sequence = spell_sprite_sequences[spell_id];
        falling_spell_cursor->frame_countdown = 0;
        falling_spell_cursor->variant = variant;
        falling_spell_cursor->spell_id = spell_id;
        submit_audio_request(AUDIO_ID_FALLING_SPELL);
        ++spell_count;
    }
}

void resize_racket(void)
{
    if (motion_dir > 0)
        submit_audio_request(AUDIO_ID_RACKET_RESIZE);
    player_key_flags->control_flags |= PLAYER_CONTROL_FLAG_20;
    racket_object->shield_frame_timer = 3;
    temp = racket_object->sprite_frame_index + motion_dir;
    if (temp > 12) temp = 12;
    if (temp < 0) temp = 0;
    racket_object->shield_frame_index = temp;
}

void tick_racket_capture(void)
{
    int racket_unshielded;
    int has_active_timer;
    if (racket_object->capture_timer > 0) has_active_timer = 1; else has_active_timer = 0;
    if ((player_key_flags->control_flags & PLAYER_CONTROL_FLAG_08) == 0) racket_unshielded = 1; else racket_unshielded = 0;
    if (racket_unshielded | has_active_timer) {
        submit_audio_request(AUDIO_ID_BALL_CAPTURE);
        if (--racket_object->capture_timer < 0)
            start_racket_release_animation();
    }
}

void update_racket_effect(void)
{
    submit_audio_request(AUDIO_ID_RACKET_EFFECT);
    racket_object->reward_level += motion_dir;
}

void attach_ball_to_racket(void)
{
    submit_audio_request(AUDIO_ID_BALL_ATTACH);
    if ((player_key_flags->control_flags & PLAYER_CONTROL_FLAG_08) == 0) {
        if ((player_key_flags->control_flags & PLAYER_CONTROL_FLAG_BALL_ATTACHED) == 0) {
            player_key_flags->control_flags |= PLAYER_CONTROL_FLAG_BALL_ATTACHED;
            racket_object->x = racket_object->max_x + racket_object->min_x - mouse_x_average_recent;
            racket_object->y = mouse_y_mean_recent;
            move_mouse_to(racket_object->x, racket_object->y);
            racket_object->horizontal_recenter_timer = motion_dir << RACKET_RECENTER_STEP_SHIFT;
        } else {
            racket_object->horizontal_recenter_timer += motion_dir << RACKET_RECENTER_STEP_SHIFT;
        }
    }
}

void reverse_bonus_motion(void)
{
    motion_dir = -motion_dir;
    adjust_active_bonuses();
}

void play_bonus_effect(void)
{
    submit_audio_request(AUDIO_ID_BONUS_ANIMATION);
    spawn_animated_sprite(0, 0, 0, 0, spell_art_base, bonus_effect_animation_frames, 13);
}

void award_bonus_score(void)
{
    submit_audio_request(AUDIO_ID_POWERUP);
    score_state->life_balance += motion_dir * POINTS_PER_SCORE_UNIT;
}

void spawn_side_bonus(void) {
    submit_audio_request(AUDIO_ID_POWERUP);
    spawn_game_ball(racket_object->x, racket_object->y);
}

void adjust_active_bonuses(void) {
    submit_audio_request(AUDIO_ID_BONUS_MOTION);
    current_ball_pointer = game_balls;
    for (game_ball_slot = 0; game_ball_slot < current_ball_count; ++game_ball_slot) {
        temp = current_ball_pointer->behavior + motion_dir;
        if (temp > GAME_BALL_BEHAVIOR_MAX) temp = GAME_BALL_BEHAVIOR_MAX;
        if (temp < 0) temp = 0;
        current_ball_pointer->behavior = (unsigned char)temp;
        ++current_ball_pointer;
    }
}

void animate_racket_shield(void) {
    submit_audio_request(AUDIO_ID_RACKET_SHIELD);
    player_key_flags->spell_flags |= PLAYER_SPELL_FLAG_SHIELD;
    write_dac_palette(palette_base, 0, 0x100, 0x20);
    racket_object->state_30 += motion_dir << RACKET_SHIELD_STEP_SHIFT;
}

void update_all_bonus_effects(void) {
    submit_audio_request(AUDIO_ID_RACKET_EFFECT);
    work_value = 3;
    current_ball_pointer = game_balls;
    for (game_ball_slot = 0; game_ball_slot < current_ball_count; ++game_ball_slot) {
        adjust_game_ball_velocity();
        current_ball_pointer++;
    }
}

void reverse_all_bonuses(void) {
    motion_dir = -motion_dir;
    update_all_bonus_effects();
}

void trigger_racket_slide(void) {
    submit_audio_request(AUDIO_ID_RACKET_SLIDE);
    player_key_flags->spell_flags &= PLAYER_SPELL_FLAG_CLEAR_EXTEND;
    player_key_flags->control_flags |= PLAYER_CONTROL_FLAG_08;
    racket_object->effect_state = motion_dir << RACKET_SLIDE_STEP_SHIFT;
    player_key_flags->spell_flags &= PLAYER_SPELL_FLAG_CLEAR_EXTEND;
    if (player_key_flags->control_flags & PLAYER_CONTROL_FLAG_BALL_ATTACHED) {
        player_key_flags->control_flags &= PLAYER_CONTROL_FLAG_CLEAR_BALL_ATTACHED;
        racket_object->x = racket_object->max_x + racket_object->min_x - (short)mouse_x_average_recent;
        racket_object->y = (short)mouse_y_mean_recent;
        move_mouse_to(racket_object->x, racket_object->y);
    }
}

void shrink_racket(void) {
    submit_audio_request(AUDIO_ID_RACKET_SHRINK);
    if (!(player_key_flags->spell_flags & 4)) {
        racket_object->y = racket_object->max_y;
        player_key_flags->spell_flags |= PLAYER_SPELL_FLAG_SHRINK;
        update_racket_movement_bounds();
    }
}

void extend_racket(void) {
    submit_audio_request(AUDIO_ID_BALL_ATTACH);
    if (!(player_key_flags->control_flags & 8)) {
        player_key_flags->spell_flags |= PLAYER_SPELL_FLAG_EXTEND;
        racket_object->vertical_recenter_timer += motion_dir << RACKET_HEIGHT_STEP_SHIFT;
    }
}

void advance_racket_anim(void) {
    submit_audio_request(AUDIO_ID_POWERUP);
    if (!racket_object->capture_timer) {
        racket_object->effect_frame_44 = 0;
        racket_object->effect_timer_40 = 3;
    }
    racket_object->capture_timer += motion_dir;
}

