void apply_area_spell(void) {
    submit_audio_request(AUDIO_ID_AREA_SPELL);
    player_key_flags->spell_flags |= PLAYER_SPELL_FLAG_AREA;
    racket_object->state_2c += motion_dir << 9;
    current_ball_pointer = game_balls;
    for (game_ball_slot = 0; game_ball_slot < current_ball_count; ++game_ball_slot) {
        current_ball_pointer->flags |= GAME_BALL_FLAG_AREA_SPELL;
        ++current_ball_pointer;
    }
}

